-- is_admin(): service GUC bypass OR user.role in (admin, superadmin).
-- Must live after "user" exists — SQL functions validate relations at CREATE.
CREATE OR REPLACE FUNCTION app_private.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
    SELECT COALESCE(current_setting('app.service', true), '') = 'true'
    OR EXISTS (
        SELECT 1
        FROM public."user" AS u
        WHERE u.id = app_private.current_user_id()
        AND u.role IN ('admin', 'superadmin')
    );
$$;

REVOKE ALL ON FUNCTION app_private.is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_private.is_admin() TO starter_app;
--> statement-breakpoint
CREATE POLICY "rls_policy" ON "admin_action" AS PERMISSIVE FOR ALL TO "starter_app" USING (app_private.is_admin()) WITH CHECK (app_private.is_admin());--> statement-breakpoint
CREATE POLICY "rls_user_read" ON "purchase" AS PERMISSIVE FOR SELECT TO "starter_app" USING (app_private.is_admin() OR user_id = app_private.current_user_id());--> statement-breakpoint
CREATE POLICY "rls_service_write" ON "purchase" AS PERMISSIVE FOR ALL TO "starter_app" USING (app_private.is_admin()) WITH CHECK (app_private.is_admin());--> statement-breakpoint
CREATE POLICY "rls_policy" ON "system_config" AS PERMISSIVE FOR ALL TO "starter_app" USING (app_private.is_admin()) WITH CHECK (app_private.is_admin());
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO starter_app;
